# filename: parse_seahorse_island_pdf.py
import pdfplumber
import re
import statistics

pdf_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/67e8878b-5cef-4375-804e-e6291fdbe78a.pdf"

section_types = {"Hotels", "Motels", "Villas", "Guesthouses", "Inns", "Resorts", "Cottages", "B&Bs"}
current_type = None
ratings_by_type = {}

pattern = re.compile(r"(\d+(?:\.\d+)?)")  # capture numeric rating

with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        text = page.extract_text() or ""
        for line in text.splitlines():
            line = line.strip()
            if line in section_types:
                current_type = line
                if current_type not in ratings_by_type:
                    ratings_by_type[current_type] = []
                continue
            if current_type is None:
                continue
            # Search for 'Rating (out of 5)' numbers or standalone numbers in line
            match = pattern.search(line)
            if match:
                try:
                    rating = float(match.group(1))
                except:
                    continue
                # Add rating to current type
                ratings_by_type.setdefault(current_type, []).append(rating)

# Compute averages for non-empty types
summary = {}
for t, vals in ratings_by_type.items():
    if vals:
        avg = sum(vals)/len(vals)
        summary[t] = {
            'count': len(vals),
            'avg': avg
        }

print("Summary by type:")
for t in sorted(summary.keys()):
    print(f"{t}: count={summary[t]['count']}, avg={summary[t]['avg']:.2f}")

# Identify higher average among present types
present_types = list(summary.keys())
if present_types:
    best_type = max(present_types, key=lambda t: summary[t]['avg'])
    print(f"\nHighest average rating type: {best_type} ({summary[best_type]['avg']:.2f})")
else:
    print("No ratings found.")
